package app.careerflow.mobile
import android.content.ContentValues
import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.platform.app.InstrumentationRegistry
import org.json.JSONArray
import org.json.JSONObject
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith

@RunWith(AndroidJUnit4::class)
class AssistantSchedulesTest {
 private val c=InstrumentationRegistry.getInstrumentation().targetContext
 private lateinit var s:LocalStore
 private lateinit var actions:AssistantSchedules
 @Before fun setup(){c.deleteDatabase("assistant-schedules-test.db");s=LocalStore(c,"assistant-schedules-test.db");actions=AssistantSchedules(s)}
 @After fun cleanup(){s.close();c.deleteDatabase("assistant-schedules-test.db")}
 private val body="示例科技工程师面试时间2026年11月2日14:00至2026年11月2日15:00，地点会议室A。"
 private val event=Event(company="示例科技",role="工程师",stage="interview",start="2026-11-02T14:00",end="2026-11-02T15:00",location="会议室A",evidence=body)
 private fun notice(text:String=body,n:Long=1)=s.save("HR",text,n,if(n%2==0L)"sms" else "email","test-$n")
 private fun schedule(n:Long,e:Event=event,done:Boolean=false):Long {val id=s.writableDatabase.insertOrThrow("schedules",null,ContentValues().apply{put("data",EventJson.write(e).toString());put("done",if(done)1 else 0)});s.writableDatabase.execSQL("INSERT INTO evidence(notice,ordinal,schedule) VALUES(?,0,?)",arrayOf(n,id));return id}
 private fun run(a:JSONObject,key:String=java.util.UUID.randomUUID().toString(),context:JSONObject=AssistantContext.build(s,"示例科技"))=actions.execute(JSONObject().put("scheduleActions",JSONArray().put(a)),context,key)
 private fun merge(a:Long,b:Long)=JSONObject().put("type","merge").put("keep",a).put("remove",b).put("reason","同公司同岗位同一场面试")
 @Test fun duplicateMergePreservesSourcesCompletionReceiptsAndIsIdempotent(){val a=schedule(notice());val b=schedule(notice(n=2),done=true);s.delivery("$b:123");val ctx=AssistantContext.build(s,"示例科技");val command=merge(a,b);val out=run(command,"once",ctx);assertTrue(out.toString().contains("Merged"));assertEquals(1,s.schedules().length());assertTrue(s.schedules().getJSONObject(0).getBoolean("done"));assertEquals(2,s.sources(a).length());assertTrue(s.delivered("$a:123"));assertEquals(out.toString(),run(command,"once",ctx).toString());assertTrue(s.history().toString().contains("beforeRemove"));assertEquals(2,s.noticeCount())}
 @Test fun ambiguousMergeAsksAndConfirmationUsesSavedPlan(){val a=schedule(notice(),event.copy(round="AI面试"));val b=schedule(notice(n=2),event.copy(round="技术面试"));run(merge(a,b));assertEquals(2,s.schedules().length());val pending=actions.pending().getJSONObject(0);assertTrue(pending.getString("question").contains("技术面试"));actions.execute(JSONObject().put("confirmPending",JSONArray().put(pending.getString("id"))),AssistantContext.build(s,"示例科技"),"confirm");assertEquals(1,s.schedules().length());assertTrue(JSONObject(s.history().getJSONObject(0).getString("detail")).getBoolean("confirmed"))}
 @Test fun staleConfirmationCannotOverrideRecentManualChanges(){val a=schedule(notice(),event.copy(round="AI"));val b=schedule(notice(n=2),event.copy(round="技术"));run(merge(a,b));val pending=actions.pending().getJSONObject(0);s.manual(EventJson.write(event.copy(location="用户地点")).put("id",a));val out=actions.execute(JSONObject().put("confirmPending",JSONArray().put(pending.getString("id"))),AssistantContext.build(s,"示例科技"),"stale");assertTrue(out.toString().contains("changed"));assertEquals(2,s.schedules().length())}
 @Test fun locationOnlySmsUpdatesWithoutLosingTimeOrCompletion(){val id=schedule(notice(),done=true);val text="示例科技工程师面试地点更新为会议室B，时间不变。";val n=notice(text,2);val e=event.copy(start="",end="",location="会议室B",evidence=text,action="update");run(JSONObject().put("type","update").put("scheduleId",id).put("noticeId",n).put("event",EventJson.write(e)));val result=s.schedules().getJSONObject(0);assertEquals("会议室B",result.getString("location"));assertEquals(event.start,result.getString("start"));assertTrue(result.getBoolean("done"));assertEquals(2,s.sources(id).length());assertTrue(s.history().toString().contains("before"))}
 @Test fun forgedEvidenceAndUnseenSourcesCannotChangeTime(){val id=schedule(notice());val n=notice("示例科技招聘通知",2);val command=JSONObject().put("type","update").put("scheduleId",id).put("noticeId",n).put("event",EventJson.write(event.copy(start="2026-11-03T14:00")));run(command);assertEquals(event.start,s.schedules().getJSONObject(0).getString("start"));val ctx=AssistantContext.build(s,"示例科技").put("notices",JSONArray());assertTrue(run(command,context=ctx).toString().contains("Source not retrieved"))}
 @Test fun missingReminderCreatesOnceAndKeepsSource(){val n=notice();val command=JSONObject().put("type","create").put("noticeId",n).put("event",EventJson.write(event));run(command);run(command);assertEquals(1,s.schedules().length());assertEquals(1,s.sources(s.schedules().getJSONObject(0).getLong("id")).length());assertNotNull(ScheduleRules.due(EventJson.read(s.schedules().getJSONObject(0))))}
 @Test fun oldSourcesAndManualLocationsRequireClarification(){val id=schedule(notice(n=3));val n=notice("示例科技面试地点会议室B",2);val e=event.copy(start="",end="",location="会议室B",action="update",evidence="示例科技面试地点会议室B");run(JSONObject().put("type","update").put("scheduleId",id).put("noticeId",n).put("event",EventJson.write(e)));assertEquals("会议室A",s.schedules().getJSONObject(0).getString("location"));assertEquals(1,actions.pending().length())}
 @Test fun graphIsPagedAndDoesNotMaterializeOriginalText(){repeat(45){i->schedule(notice(n=i+1L))};val page=RelationshipMap.page(s,"示例",20);assertEquals(45,page.getInt("total"));assertEquals(20,page.getJSONArray("schedules").length());val source=page.getJSONArray("schedules").getJSONObject(0).getJSONArray("links").getJSONObject(0);assertTrue(source.has("id"));assertFalse(source.has("body"))}
 @Test fun malformedModelFieldsProduceRepairFeedbackBeforeAnyWrite(){val n=notice();val id=schedule(n);val command=JSONObject().put("type","update").put("noticeId",n).put("scheduleId",id).put("event",EventJson.write(event).put("stage","面试"));val result=JSONObject().put("scheduleActions",JSONArray().put(command));assertTrue(actions.invalid(result,AssistantContext.build(s,"示例科技")).toString().contains("English enum"));assertEquals(1,s.schedules().getJSONObject(0).getInt("revision"));command.getJSONObject("event").put("stage","interview");assertEquals(0,actions.invalid(result,AssistantContext.build(s,"示例科技")).length())}
 @Test fun correctedStartDoesNotRetainAnEarlierOldEnd(){val text="示例科技工程师面试时间2026年11月2日16:00";val n=notice(text);val id=schedule(n,event,true);val e=event.copy(start="2026-11-02T16:00",end="",location="",evidence=text,action="update");run(JSONObject().put("type","update").put("scheduleId",id).put("noticeId",n).put("event",EventJson.write(e)));val result=s.schedules().getJSONObject(0);assertEquals("",result.getString("end"));assertTrue(result.getBoolean("done"))}
 @Test fun retrievalFindsOldNamedNoticeBeyondRecentTwoHundred(){val target=notice("远方科技工程师面试2026年11月2日14:00",1);repeat(230){notice("其他公司招聘通知",it+2L)};val context=AssistantContext.build(s,"核对通知 #$target");assertTrue(context.getJSONArray("notices").toString().contains("远方科技"));assertTrue(context.getJSONArray("notices").length()<=40)}
}
